package globclient

import kyo.*

object GlobLiteralFixture:
    val value: Glob = glob"src/**/*.{scala,java}"
    val maximum: Glob =
        glob"*[!a-c]"
end GlobLiteralFixture

class GlobExternalTest extends kyo.test.Test[Any]:

    "literal expansion is usable outside the kyo package" in {
        val sources = GlobLiteralFixture.value
        assert(sources.show == "src/**/*.{scala,java}")
        assert(sources.matches("src/main/App.scala", Glob.CaseSensitivity.Sensitive))
        assert(!sources.matches("test/main/App.scala", Glob.CaseSensitivity.Sensitive))
    }

    "maximum-length literal expansion is usable outside the kyo package" in {
        val pattern = "*[!a-c]" + "a" * (4096 - 7)
        val maximum = GlobLiteralFixture.maximum
        assert(maximum.show == pattern)
        assert(maximum.matches("z" + "a" * (4096 - 7), Glob.CaseSensitivity.Sensitive))
        assert(!maximum.matches("a" * (4096 - 6), Glob.CaseSensitivity.Sensitive))
    }
end GlobExternalTest
